import Element from './Element';
import ActionData from '../actions/ActionData';
import Timeline from '../../animation/Timeline';
import TouchManager from '../TouchManager';
import Runtime from '../../../Runtime';
import {AssetDescriptor} from '../ViewManager';

/**
 * Button element.
 * Can be assigned {@link jibo.face.ActionData}, which are triggered on button click.
 *
 * @class Button
 * @extends jibo.face.Element
 * @memberof jibo.face
 */
class Button extends Element
{
    /**
     * The default class identifier.
     * Generally used to register the class.
     * @name jibo.face.Button.DEFAULT_TYPE
     * @type {String}
     * @readOnly
     * @internal
     */
    public static get DEFAULT_TYPE():string {return 'Button';}

    /**
     * `PIXI.animate.MovieClip` containing button states.
     * Buttons do not require MovieClips, so if a `PIXI.animate.Timeline`
     * is not given as the base asset this remains undefined.
     * @name jibo.face.Button#timeline
     * @type {PIXI.animate.MovieClip}
     */
    public timeline:PIXI.animate.MovieClip = null;

    /**
     * The Class name as a string.
     * @name jibo.face.Button#_type
     * @type {String}
     * @protected
     * @internal
     */
    protected _type:string = Button.DEFAULT_TYPE;

    /**
     * Flag used to keep track if button is down.
     * @name jibo.face.Button#_isDown
     * @type {Boolean}
     * @protected
     * @internal
     */
    protected _isDown:boolean = false;

    /**
     * Create a Button from a configuration Object derived from JSON.
     * @method jibo.face.Button.createFromConfig
     * @param {Object} configData Object derived from JSON, must be a specific format refer to examples.
     * @returns {jibo.face.Button} Returns the Button created from the given configuration.
     */
    public static createFromConfig(configData:any):Button
    {
        let btn:Button = new Button();
        btn.assignConfig(configData);
        return btn;
    }

    /**
     * Create a Button object by passing the DisplayObject and specifying the {@link jibo.faceActionData}.
     * This allows for a more direct way to create Buttons that is not reliant on the configuration data.
     * @method jibo.face.Button.createFromDisplayObject
     * @param {PIXI.DisplayObject} displayObject The DisplayObject with the button assets.
     * @param {jibo.face.ActionData} [actionData] The action to be triggered on button click.
     * @param {PIXI.Container} container Display container for the button.
     * @returns {jibo.face.Button} Returns the created Button.
     */
    public static createFromDisplayObject(displayObject:PIXI.DisplayObject, actionData?:ActionData, container:PIXI.Container=null):Button
    {
        let btn:Button = new Button();

        btn.display = new PIXI.Container();
        if(container){
            container.addChild(btn.display );
        }
        else if(displayObject.parent) {
            displayObject.parent.addChild(btn.display);
        }

        if(actionData) {
            btn.addAction(actionData);
        }

        btn.setupHitArea();
        btn.setupInteractions();
        btn.display.addChild(displayObject);
        return btn;
    }

    constructor(){
        super();
        this.interactable = true;
    }

    /**
     * Set up the display.
     * Assign assets, set timelines, etc.
     * @method jibo.face.Button#setupDisplay
     * @param {Object} [assets] - Object passed back from loader namespace load method,
     *        refer to {@link jibo.loader} for details.
     */
    public setupDisplay(assets?:any):void
    {
        // using asset descriptors identified which asset(s) within given assets should be added to display
        let asset:any;
        let assetDescriptor:AssetDescriptor;
        for(let i:number = 0; i<this._assetDescriptors.length; i++) {

            assetDescriptor = this._assetDescriptors[i];
            asset = assets[assetDescriptor.id];
            if(assetDescriptor.hasOwnProperty('type')) {
                switch (assetDescriptor.type) {
                    case 'texture':
                        let sprite:PIXI.Sprite = new PIXI.Sprite(asset);
                        this.display.addChild(sprite);
                        break;
                    case 'timeline':
                        // NOTE :: Assuming possibility of multiple buttons, so we create a new instance
                        let movieClip:PIXI.animate.MovieClip = new (asset as Timeline).library.stage();
                        this.display.addChild(movieClip);
                        // if Timeline did not create an instance on load and flagged for upload, upload now
                        if(!assetDescriptor.instance && assetDescriptor.upload) {
                            (<any>Runtime.instance.face).plugins.prepare.upload(movieClip); 
                        }
                        break;
                    default:
                        console.log('Button :: assignAssets : not a valid type: ' + asset.type);
                }
            }
            else {
                console.log('Button :: assignAssets : no type given for asset: ' + asset + ' assuming bitmap');
                let sprite:PIXI.Sprite = PIXI.Sprite.from(asset);
                this.display.addChild(sprite);
            }
        }

        //set up interactions, add to container, set flag
        this.setupHitArea();
        this.setupInteractions();
    }

    /**
     * Define the interactive hit area of the display.
     * The DisplayObject.hitArea is what Pixi uses to define the interactive area.
     * @method jibo.face.Button#setupHitArea
     * @param {PIXI.Rectangle} [bounds] Optionally specify the bounds for the hit area.
     *  If not defined, defaults to using the display's bounds.
     *  @internal
     */
    public setupHitArea(bounds?:PIXI.Rectangle):void {

        if(this.display){
            if(bounds){
                this.display.hitArea = bounds;
            }
            else{
                bounds = this.display.getBounds();
                // set x and y position back to zero as getBounds() returns stage relative position
                bounds.x = bounds.y = 0;
                this.display.hitArea = bounds;
            }
        }
    }

    /**
     * Set up button to listen and react to touch inputs.
     * @method jibo.face.Button#setupInteractions
     * @internal
     */
    public setupInteractions() {
        if(this.display && this.interactable) {

            this.display.interactiveChildren = false;
            this.display.interactive = !this._inputLocked;

            // add listener for rollover, handled by PIXI, click/tap is handled by gestures
            this.display.addListener('mouseout',this.out.bind(this));
            this.display.addListener('mousedown',this.down.bind(this));
            this.display.addListener('mouseup',this.up.bind(this));
        }
    }

    /**
     * Lock or unlock input, lock value is applied to the display's interactive variable.
     * @method jibo.face.Button#lockInput
     * @param {Boolean} flag - Determines if input is locked.
     */
    public lockInput(flag:boolean):void{
        super.lockInput(flag);
        if(this.interactable && this.display) {
            if(flag && this._isDown){
                this.up();
            }
        }
    }

    /**
     * Manually force a click.
     * @method jibo.face.Button#click
     * @param {any} mouseData Returned from Pixi.
     * @protected
     */
    protected click() {
        if(this.timeline) {
            PIXI.animate.Animator.stop(this.timeline);
        }
        super.triggerActions(TouchManager.TAP);
    }

    /**
     * Handler for out touch input.
     * @method jibo.face.Button#out
     * @param {any} mouseData Returned from Pixi.
     * @protected
     */
    protected out(mouseData?:any) {
        if(this._isDown) {
            this._isDown = false;
            if(this.timeline){
                PIXI.animate.Animator.play(this.timeline, 'out');
            }
        }
    }

    /**
     * Handler for down touch input.
     * @method jibo.face.Button#down
     * @param {any} mouseData Returned from Pixi.
     * @protected
     */
    protected down(mouseData?:any) {
        this._isDown = true;
        if(this.timeline){
            PIXI.animate.Animator.play(this.timeline, 'down');
        }
    }

    /**
     * Handler for up touch input.
     * @method jibo.face.Button#up
     * @param {any} mouseData Returned from Pixi.
     * @protected
     */
    protected up(mouseData?:any){
        this._isDown = false;
        if(this.timeline) {
            PIXI.animate.Animator.play(this.timeline, 'up');
        }
    }

    /**
     * Activate the button, used for non-touch input.
     * @method jibo.face.Button#activate
     * @protected
     */
    public activate():void{
        if(this.timeline) {
            PIXI.animate.Animator.play(this.timeline, 'activate');
        }
    }

    /**
     * Destroy, stops any tweens that may be active on the Elements' display.
     * @method jibo.face.Button#destroy
     * @internal
     */
    public destroy():void {
        if(this.display){
            this.display.removeAllListeners('mouseout');
            this.display.removeAllListeners('mousedown');
            this.display.removeAllListeners('mouseup');
            this.display.removeAllListeners('click');
        }
        this.timeline = null;
        super.destroy();

    }
}

export default Button;
