import Runtime from '../../Runtime';
import GestureManager from '../input/GestureManager';
import View from './views/View';
import Element from './components/Element';
import Component from './Component';
import FaceRenderer from '../FaceRenderer';
import ViewManager from './ViewManager';

/**
 * Manages interactions for the GUI.
 * @class TouchManager
 * @memberof jibo.face
 * @internal
 */
class TouchManager
{
    /**
     * Tap gesture type.
     * @type {string}
     * @name jibo.face.TouchManager.TAP
     * @readOnly
     */
    public static TAP:string = 'tap';

    /**
     * Swipe down gesture type.
     * @type {string}
     * @name jibo.face.TouchManager.SWIPE
     * @readOnly
     */
    public static SWIPE:string = 'swipeDown';

    /**
     * Pan horizontal gesture type.
     * @type {string}
     * @name jibo.face.TouchManager.PAN
     * @readOnly
     */
    public static PAN:string = 'pan';

    /**
     * Instance used for singleton.
     * @name jibo.face.TouchManager._instance
     * @type {jibo.face.TouchManager}
     * @private
     */
    private static _instance:TouchManager = null;

    /**
     * Gets singleton instance of TouchManager.
     * @name jibo.face.TouchManager#instance
     * @type {jibo.face.TouchManager}
     * @readonly
     */
    public static get instance():TouchManager {
        return TouchManager._instance;
    }

    /**
     * Pixi interaction manager reference.
     * @type {PIXI.interation.TouchManager}
     * @name jibo.face.TouchManager#_pixiViewGestureManager
     * @private
     */
    private _interactionManager:PIXI.interaction.InteractionManager = null;

    /**
     * Reference to canvas element.
     * @type {Object}
     * @name jibo.face.TouchManager#_canvas
     * @private
     */
    private _canvas:any = null;

    /**
     * Reference to GestureManager instance.
     * @type {jibo.face.GestureManager}
     * @name jibo.face.TouchManager#_gestureManager
     * @private
     */
    private _gestureManager:GestureManager = null;

    /**
     * Reference to ViewManager instance.
     * @type {jibo.face.ViewManager}
     * @name jibo.face.TouchManager#_viewManager
     * @private
     */
    private _viewManager:ViewManager = null;

    /**
     * Reference to the tap gesture.
     * @type {any}
     * @name jibo.face.TouchManager#_tapGesture
     * @private
     */
    private _tapGesture:any = null;

    /**
     * Reference to the swipe down gesture.
     * @name jibo.face.TouchManager#_swipeDownGesture
     * @type {any}
     * @private
     */
    private _swipeDownGesture:any = null;

    /**
     * Reference to the pan horizontal gesture.
     * @name jibo.face.TouchManager#_panHorizontalGesture
     * @type {any}
     * @private
     */
    private _panHorizontalGesture:any = null;

    /**
     * Holds reference to input position for hit testing.
     * @name jibo.face.TouchManager#_inputPoint
     * @type {PIXI.Point}
     * @private
     */
    private _inputPoint:PIXI.Point = null;

    ///////////////////////////// CONSTRUCTION /////////////////////////////

    /**
     * Constructor.
     * @param {PIXI.WebGLRenderer} renderer
     * @param {jibo.face.ViewManager} viewManager
     * @method jibo.face.TouchManager#constructor
     * @internal
     */
    constructor(renderer:FaceRenderer, viewManager:ViewManager) {
        // Check for singleton, if undefined define
        if (!TouchManager._instance) {
            TouchManager._instance = this;
            // Note :: Using brackets because this is a protected method, and TS doesn't like us accessing it.
            this._interactionManager = (<FaceRenderer>renderer)['plugins'].interaction;
            this._viewManager = viewManager;
            this._canvas = renderer.view;
            // bind functions
            this.onViewportOut = this.onViewportOut.bind(this);
            this.isComponentHit = this.isComponentHit.bind(this);
        }
    }

    /**
     * Initialize, gets reference to GestureManager and creates viewport out listener.
     * @method jibo.face.TouchManager#init
     * @internal
     */
    public init():void {
        this._gestureManager = Runtime.instance.face.gestures;
        this._inputPoint = new PIXI.Point();
        // NOTE :: this is really only necessary for simulator, on robot will receive a mouse up triggering appropriate response from gesture
        this.addViewportOut();
    }

    /**
     * Remove gesture by type.
     * @method jibo.face.TouchManager#addGesture
     * @param {String} [gesture = 'tap'] - type of gesture to remove.
     * @param {Function} [gestureEventCallback] - For use with Pan gesture, handler called on each pan event.
     */
    public addGesture(gesture:string = GestureManager.TAP, gestureEventCallback?:(hammerEvent: {}) => void):void {

        switch(gesture) {
            case TouchManager.TAP:
                this.createTapGesture();
                break;
            case TouchManager.SWIPE:
                this.createSwipeDownGesture();
                break;
            case TouchManager.PAN:
                this.createPanHorizontalGesture(gestureEventCallback);
                break;
            default:
                console.log('TouchManager :: addGesture : ' + gesture + ' not supported.');
                break;
        }
    }

    /**
     * Remove gesture by type.
     * @method jibo.face.TouchManager#removeGesture
     * @param {String} [gesture = 'tap'] - type of gesture to remove.
     */
    public removeGesture(gesture:string = GestureManager.TAP):void {

        switch(gesture){
            case TouchManager.TAP:
                if(this._tapGesture) {
                    this._gestureManager.removeStageGesture(this._tapGesture);
                    this._tapGesture = null;
                }
                break;
            case TouchManager.SWIPE:
                if(this._swipeDownGesture) {
                    this._gestureManager.removeStageGesture(this._swipeDownGesture);
                    this._swipeDownGesture = null;
                }
                break;
            case TouchManager.PAN:
                if(this._panHorizontalGesture) {
                    this._gestureManager.removeStageGesture(this._panHorizontalGesture);
                    this._panHorizontalGesture = null;
                }
                break;
            default:
                console.log('InteractionManger :: removeGesture : ' + gesture + ' not supported.');
                return;
        }
    }

    /**
     * Remove all possible TouchManager gestures.
     * @method jibo.face.TouchManager#removeAllGestures
     */
    public removeAllGestures():void {
        this.removeGesture(TouchManager.TAP);
        this.removeGesture(TouchManager.SWIPE);
        this.removeGesture(TouchManager.PAN);
        // TODO :: remove viewport out?
    }

    /**
     * Create gestures required by Component tree.
     * NOTE :: Does not create pan gesture, must be created by Component that requires it.
     * @method jibo.face.TouchManager#createRequiredGestures
     * @param view {jibo.face.View} View to create gestures for.
     */
    public createRequiredGestures(view:View):void {

        // determine which gestures we don't have
        let possibleGestures:string[] = [];
        if(!this._tapGesture){
            possibleGestures.push(TouchManager.TAP);
        }
        if(!this._swipeDownGesture){
            possibleGestures.push(TouchManager.SWIPE);
        }
        /*
        if(!this._panHorizontalGesture){
            possibleGestures.push(TouchManager.PAN);
        }
        */

        // iterate through components to determine what gestures are required
        let i:number;
        if (possibleGestures.length > 0 && view) {
            view.findComponent((component:Component) => {
                if (component.hasTouchInteractive) {
                    for (i = possibleGestures.length; i >= 0; i--) {
                        if (component.hasActions(possibleGestures[i])) {
                            this.addGesture(possibleGestures[i]);
                            possibleGestures.splice(i, 1);
                            if (possibleGestures.length === 0) {
                                return true;
                            }
                        }
                    }
                }
                return false;
            });
        }
    }

    /**
     * Destroy.
     * @method jibo.face.TouchManager#destroy
     */
    public destroy():void {
        this.removeAllGestures();
        this.removeViewportOut();
        this._canvas = null;
        this._interactionManager = null;
        this._viewManager = null;
        this._gestureManager = null;
        this._inputPoint = null;

    }

    /**
     * Add listener for input exiting viewport.
     * @method jibo.face.TouchManager#addViewportOut
     * @private
     */
    private addViewportOut():void {
        if(this._canvas){
            this._canvas.addEventListener('mouseleave', this.onViewportOut);
        }
    }

    /**
     * Remove listener for input exiting viewport.
     * @method jibo.face.TouchManager#removeViewportOut
     * @private
     */
    private removeViewportOut():void {
        if(this._canvas) {
            this._canvas.removeEventListener('mouseleave', this.onViewportOut);
        }
    }

    /**
     * Create listener for input exiting viewport.
     * @method jibo.face.TouchManager#createViewportOut
     * @private
     */
    private onViewportOut():void {
        this._gestureManager.stop();
        if(this._panHorizontalGesture){
            this._panHorizontalGesture.emit({isFinal:true});
        }
    }

    ///////////////////////////////// TAP /////////////////////////////////

    /**
     * Create a gesture for tap.
     * Refer to HammerJS documentation for Tap values {@link http://hammerjs.github.io/recognizer-tap}
     * @method jibo.face.TouchManager#createTapGesture
     * @returns {boolean} `true` if a new gesture was created.
     * @private
     */
    private createTapGesture():boolean {
        if(!this._tapGesture){
            this._tapGesture = this._gestureManager.addStageGesture(
                this._gestureManager.hammer.Tap,
                {
                    event: GestureManager.TAP,
                    time:1000,       // Maximum press time in ms.
                    interval:100,   // Maximum time in ms between multiple taps.
                    threshold:4     // While doing a tap some small movement is allowed.
                },
                this.tapHandler.bind(this)
            );
            return true;
        }
        return false;
    }

    /**
     * Handler for tap complete event.
     * @method jibo.face.TouchManager#tapHandler
     * @param gestureEvent {any}
     * @private
     */
    private tapHandler(gestureEvent:any):void{

        // check if there is a view with a tap, if so call view's tap handler
        const currentView:View = this._viewManager.currentView;
        if(currentView && !currentView.inputLocked) {
            // if there are tap actions on view, view takes precedence
            if (currentView.isTouchInteractive && currentView.hasActions(TouchManager.TAP)) {
                currentView.triggerActions(TouchManager.TAP);
            }
            else {
                // see if tap happens over an interactive component
                // update input position
                this._inputPoint.x = gestureEvent.pointers[0].clientX;
                this._inputPoint.y = gestureEvent.pointers[0].clientY;

                const overComponent:Component = currentView.findComponent(this.isComponentHit);
                // if component found trigger any tap actions
                if (overComponent) {
                    overComponent.triggerActions(TouchManager.TAP);
                }
            }
        }
    }

    /**
     * Hit test Component against current input point.
     * @method jibo.face.TouchManager#isComponentHit
     * @param {jibo.face.Component} component - Component to check for touch interactivity and hit.
     * @returns {boolean} `true` if Component has touch interactivity and if current input 'hits' display.
     * @private
     */
    private isComponentHit(component:Component):boolean {
        if (component.isTouchInteractive && (<Element>component).display && component.hasActions(TouchManager.TAP)) {
            // Note :: Using brackets because this is a protected method, and TS doesn't like us accessing it.
            return this._interactionManager['processInteractive'](
                this._inputPoint,
                (<Element>component).display,
                this.emptyProcess,
                true,
                true
            );
        }
        return false;
    }

    /**
     * Function required by PIXI processInteractive method, create method to speed up process
     * @method jibo.face.TouchManager#emptyProcess
     * @param {PIXI.DisplayObject} displayObject
     * @param {boolean} hit
     * @private
     */
    private emptyProcess(displayObject:PIXI.DisplayObject, hit:boolean):void {
        /* no opt */
    }

    ///////////////////////////////// SWIPE DOWN /////////////////////////////////

    /**
     * Create a gesture for swipe down.
     * @method jibo.face.TouchManager#createSwipeDownGesture
     * @returns {boolean} `true` if a new gesture was created.
     * @private
     */
    private createSwipeDownGesture():boolean {
        if(!this._swipeDownGesture){
            this._swipeDownGesture = this._gestureManager.addStageGesture(
                this._gestureManager.hammer.Swipe,
                {
                    event: GestureManager.SWIPEDOWN,
                    direction: this._gestureManager.hammer.DIRECTION_DOWN
                },
                this.swipeDownHandler.bind(this)
            );

            if(this._panHorizontalGesture){
                this._panHorizontalGesture.recognizeWith(this._swipeDownGesture);
            }
            return true;
        }
        return false;
    }

    /**
     * Handler for swipe down complete event.
     * Currently only activates for Views.
     * @method jibo.face.TouchManager#swipeDownHandler
     * @param gestureEvent {any}
     * @private
     */
    private swipeDownHandler(gestureEvent:any):void{
        const currentView:View = this._viewManager.currentView;
        if(currentView && currentView.isTouchInteractive)
        {
            currentView.triggerActions(TouchManager.SWIPE);
        }
    }

    ///////////////////////////////// PAN HORIZONTAL /////////////////////////////////

    /**
     * Create a gesture for horizontal pan.
     * @method jibo.face.TouchManager#createPanHorizontalGesture
     * @param {Object} gestureEventCallback
     * @returns {boolean} `true` if a new gesture was created.
     * @private
     */
    private createPanHorizontalGesture(gestureEventCallback?:(hammerEvent: {}) => void):boolean {
        if(!this._panHorizontalGesture){
            // create gesture and store reference
            this._panHorizontalGesture = this._gestureManager.addStageGesture(
                this._gestureManager.hammer.Pan,
                {
                    event: GestureManager.PAN,
                    direction: this._gestureManager.hammer.DIRECTION_HORIZONTAL
                },
                gestureEventCallback
            );

            if(this._swipeDownGesture){
                this._swipeDownGesture.recognizeWith(this._panHorizontalGesture);
            }
            return true;
        }
        else{
            // if gesture already created, calling addStageGesture will add callback to list of callbacks
            this._gestureManager.addStageGesture(
                this._gestureManager.hammer.Pan,
                {
                    event: GestureManager.PAN,
                    direction: this._gestureManager.hammer.DIRECTION_HORIZONTAL
                },
                gestureEventCallback
            );
        }
        return false;
    }

}

export default TouchManager;
