import Runtime from '../../Runtime';
import EyeContainer from './EyeContainer';
import AssetLoad from '../../loader/AssetLoad';
import DOFValues from './DOFValues';
import PathUtils from '../../utils/PathUtils';

/**
 * Abstract class for background, eye overlay and eye classes.
 * @class AbstractLayer
 * @extends PIXI.Container
 * @memberof jibo.face
 * @param {Boolean} cache `true` to cache textures.
 */
abstract class AbstractLayer extends PIXI.Container {

    /**
     * If should update according to DOFValues.
     * @name jibo.face.AbstractLayer#connected
     * @type {String}
     */
    public connected:boolean;

    /**
     * `true` if layer has been initialized.
     * @name jibo.face.AbstractLayer#initialized
     * @type {String}
     * @protected
     */
    protected initialized:boolean;

    /**
     * Current cached timestamp.
     * @name jibo.face.AbstractLayer#timestamp
     * @type {Number[]}
     * @protected
     */
    protected timestamp:Array<number>;

    /**
     * Current cached dofValues.
     * @name jibo.face.AbstractLayer#dofValues
     * @type {Number[]}
     * @protected
     */
    protected dofValues:DOFValues;

    /**
     * Empty placeholder texture.
     * @name jibo.face.AbstractLayer#_defaultTexture
     * @type {PIXI.Texture}
     * @private
     */
    private _defaultTexture:PIXI.Texture;

    /**
     * Reference to the current texture.
     * @name jibo.face.AbstractLayer#_texture
     * @type {PIXI.Texture}
     * @private
     */
    private _texture:PIXI.Texture;

    /**
     * Current path of the texture loaded/loading.
     * @name jibo.face.AbstractLayer#_texturePath
     * @type {String}
     * @private
     */
    private _texturePath:string;

    /**
     * `true` if has been destroyed.
     * @name jibo.face.AbstractLayer#_destroyed
     * @type {Boolean}
     * @private
     */
    private _destroyed:boolean;

    /**
     * If the current texture is cached/protected by animation.
     * @private
     * @name jibo.face.Background#_isExternal
     * @type {String}
     */
    private _isExternal:boolean;

    /**
     * The current asset loading
     * @name jibo.face.AbstractLayer#_load
     * @type {jibo.loader.AssetLoad}
     * @private
     */
    private _load:AssetLoad;

    constructor(public eyeContainer:EyeContainer, public cache:boolean) {

        super();
        this.x = 0;
        this.y = 0;
        this._destroyed = false;
        this._isExternal = false;
        this.connected = true;
        this.initialized = false;
    }

    /**
     * Default eye texture when nothing is set.
     * @method jibo.face.AbstractLayer#reset
     * @param {Boolean} [resetPath=true] `false` to ignore resetting default path
     */
    reset(resetPath?:boolean): void {
        if (this.initialized) {
            this._applyTexture(this._defaultTexture);
            if (resetPath !== false) {
                this._texturePath = this._defaultTexture.baseTexture.imageUrl;
            }
        }
    }

    /**
     * Default eye texture when nothing is set.
     * @method jibo.face.AbstractLayer#init
     * @param {PIXI.Texture} texture The default texture to use
     */
    init(texture:PIXI.Texture):void {
        this._defaultTexture = texture;
        this.initialized = true;
        this.reset();

        if (this.timestamp && this.dofValues) {
            this.display(this.timestamp, this.dofValues);
        }
    }

    /**
     * Display of DOFValues.
     * @method jibo.face.AbstractLayer#display
     * @param {Array<Number>} timestamp Timestamp when update is called.
     * @param {jibo.face.DOFValues} dofValues Update display according to these values.
     * @return {Boolean} `true` proceeds with update.
     */
    display(timestamp:number[], dofValues:DOFValues):boolean {

        if (!this.initialized) {
            this.timestamp = timestamp;
            this.dofValues = dofValues;
            return false;
        }
        if (!this.connected) {
            return false;
        }
        return true;
    }

    /**
     * Full path to the texture to use.
     * @name jibo.face.AbstractLayer#texturePath
     * @type {String}
     */
    set texturePath(value:string) {

        if (value !== this._texturePath) {
            this._texturePath = value;
            this._cancelLoad();

            // Ignore folders
            if (!PathUtils.isImage(value)) {
                this.reset(false); // don't reset texturePath
            }
            else {
                // Check for the texture on the keys file
                const texture = this.eyeContainer.getTexture(value);
                if (this.cache && texture) {
                    this._applyTexture(texture, true);
                }
                else if (this._isDefaultTexture(this._defaultTexture, value)) {
                    this.reset();
                }
                else {
                    this._loadTexture(value);
                }
            }
        }
    }
    get texturePath():string {
        return this._texturePath;
    }

    /**
     * Destroy and don't use after this.
     * @method jibo.face.AbstractLayer#destroy
     */
    destroy(): void {
        if (this._destroyed) {
            return;
        }
        this._cancelLoad();
        this._destroyed = true;
        this.reset();
        this._defaultTexture = null;
        this._texture = null;
        super.destroy(true);
    }

    /**
     * Set current eye texture.
     * @method jibo.face.AbstractLayer#setTexture
     * @param {PIXI.Texture} texture Texture to set.
     * @override
     */
    protected setTexture(texture:PIXI.Texture):void {
        this._texture = texture;
    }

    /**
     * Value to tint.
     * @method jibo.face.AbstractLayer#rgb2hex
     * @protected
     * @param {Number} red Red value from 0 to 1
     * @param {Number} green Green value from 0 to 1
     * @param {Number} blue Blue value from 0 to 1
     * @return {int} The resulting uint color
     */
    protected rgb2hex(red:number, green:number, blue:number): number {
        return (red * 255) << 16 | (green * 255) << 8 | (blue * 255);
    }

    /**
     * Check to see a path matches the default texture.
     * @method jibo.face.AbstractLayer#_isDefaultTexture
     * @param {PIXI.Texture} texture The default texture.
     * @param {String} value Full path to test.
     * @return {Boolean} `true` if the value is the default texture.
     * @private
     */
    private _isDefaultTexture(texture:PIXI.Texture, value:string): boolean {
        const parts = texture.baseTexture.imageUrl.split('animation-utilities');
        return parts.length === 2 && value.endsWith(parts[1]);
    }

    /**
     * If there's a current load happen, stop it.
     * @method jibo.face.AbstractLayer#_cancelLoad
     * @private
     */
    private _cancelLoad(): void {
        if (this._load) {
            this._load.cancel();
            this._load = null;
        }
    }

    /**
     * Set the current texture path.
     * @method jibo.face.AbstractLayer#_applyTexture
     * @param {String} value Path to the texture
     * @param {Boolean} [externa=false] If the images is an external resource or cache.
     * @private
     */
    private _applyTexture(texture:PIXI.Texture, external?:boolean): void {

        const oldTexture:PIXI.Texture = this._texture;

        // Not the current texture, not the default texture
        // we should clean up this texture (except texture in animations)
        if (oldTexture && texture !== oldTexture && oldTexture !== this._defaultTexture && !this._isExternal) {
            oldTexture.destroy(true);
        }
        this._isExternal = !!external;
        this.setTexture(texture);
    }

    /**
     * Set the current texture path.
     * @method jibo.face.AbstractLayer#_loadTexture
     * @param {String} value Path to the texture
     * @private
     */
    private _loadTexture(value:string):void {
        this._load = Runtime.instance.loader.load({
            id: value,
            src: value,
            cache: this.cache ? EyeContainer.CACHE_ID : false,
            type: 'texture',
            complete: (err, texture) => {
                this._load = null;
                this._applyTexture(texture);
            }
        });
    }
}

export default AbstractLayer;
