import {SensoryRecord} from "./SensoryRecord";
import {Time} from "animation-utilities";

/**
 * @class IDRecord
 * @memberof jibo.lps.identity
 * @param {string} personID Map element of id:track#
 * @internal
 */
export class IDRecord{
    [personID:string]:(number);
}

export interface Tracker{

    /**
     * When the last time this person spoke was - this allows us to use 'the last person to speak'
     * as the person currently speaking to Jibo.
     * @type {Time}
     */
    lastSpokeTime:Time;

    /**
     * @param {jibo.lps.identity.SensoryRecord} sensoryRecord
     * @param {jibo.lps.identity.IDRecord} idRecord
     */
    handleRecord(sensoryRecord:SensoryRecord, idRecord:IDRecord);

    /**
     * @param {Time} currentTime
     */
    update(currentTime:Time);

    /**
     * @return {boolean}
     */
    getIsPresent():boolean;

    /**
     * @param {Time} currentTime
     * @param {boolean} isPresent
     * @param {boolean} isSpeaking
     */
    setIsPresent(currentTime:Time, isPresent:boolean, isSpeaking:boolean);

    /**
     * @return {string} - the type of sensory input that caused presence to activate
     */
    getPresenceReason():string;

    /**
     * @return {boolean}
     */
    getShouldDelete():boolean;

}
