import {Time} from "animation-utilities";

/**
 * @description
 * Record of any type of sensory input
 * @memberOf jibo.lps.identity
 * @class SensoryRecord
 * @internal
 * @param {string} type
 * @param {THREE.Vector3} position
 * @param {object} rawData
 * @param {Time} receivedAt
 * @param {Time} reportedTS
 * @param {?} [id]
 * @param {?number} [confidence]
 */
export class SensoryRecord{

    /**
     * @type {string}
     */
    public type:string;

    /**
     * @type {THREE.Vector3}
     */
    public position:any = null;


    public raw:any;

    /**
     * @type {Time}
     */
    public receivedAt:Time;

    /**
     * @type {Time}
     */
    public reportedTS:Time;

    /**
     * @type {?}
     */
    public id:any;

    /**
     * @type {?number}
     */
    public confidence:number;

    constructor(type:string, position:any, rawData:any, receivedAt:Time, reportedTS:Time, id?:any, confidence?:number){
        this.type = type;
        if(position !== null && position !== undefined){
            this.position = position;
        }
        this.raw = rawData;
        this.receivedAt = receivedAt;
        this.reportedTS = reportedTS;
        this.id = id;
        this.confidence = confidence;
    }

}

/**
 * @description
 * Handler for any type of sensory data
 * @memberOf jibo.lps.identity
 * @class SensoryHandler
 * @internal
 */
export interface SensoryHandler{
    /**
     * @description Add data to a sensory record
     * @param {SensoryRecord} sensoryRecord Sensory record to add data to.
     * @method jibo.lps.identity.SensoryHandler#addData
     */
    addData(sensoryRecord:SensoryRecord);
}
