import {StateChanges} from "./TrackerManager";
import {IDLabels} from "./DataTypes";
import {IdentityEvents} from "./IDEvents";
import JiboLog = require("jibo-log");

/**
 * @description
 * Convert events from LPS service to IdentityEvents.
 * @class EventConverter
 * @memberof jibo.lps.identity
 * @internal
 */
class EventConverter{

    public events:IdentityEvents;
    private log:JiboLog;

    constructor(events:IdentityEvents, log:JiboLog){
        this.log = log;
        this.events = events;
    }

    ///**
    // * Represents the announced state of whether anyone is present.
    // * true means we have last announced that someone is present, false means we have last announced that someone is absent
    // * @type {boolean}
    // */
    //private stateAnyone:boolean = false;

    /**
     * @method jibo.lps.identity.EventConverter#processChanges
     * @param {StateChanges} stateChanges
     */
    public processChanges(stateChanges:StateChanges){

        let ids = Object.keys(stateChanges);
        for(let i = 0; i < ids.length; i++){
            let id = ids[i];
            let direction:boolean = stateChanges[id].direction;
            let reason:string = stateChanges[id].reason;

            if(id === IDLabels.ANYBODY){
                if(direction){
                    this.events.presenceStarted.emit({reason:reason});
                    this.log.info("Firing presence started (reason:"+reason+")");
                }else{
                    this.events.presenceEnded.emit({reason:reason});
                    this.log.info("Firing presence ended");
                }
            }else if(id === IDLabels.NOT_ENROLLED){
                ;// we don't emit events on this currently
            }else{
                if(direction){
                    let payload = {id:id, type:IDLabels.IDENTIFIED, reason:reason};
                    this.log.info("Firing ID Acquired (id:"+payload.id+" type:"+payload.type+" reason:"+payload.reason+")");
                    this.events.idAcquired.emit(payload); //TODO: push type info deeper
                }else{
                    let payload = {id:id, type:IDLabels.IDENTIFIED, reason:reason};
                    this.log.info("Firing ID lost (id:"+payload.id+" type:"+payload.type+")");
                    this.events.idLost.emit(payload); //TODO: push type info deeper
                }
            }
        }
    }

}

export default EventConverter;
