import {IDRecord, Tracker} from "./Tracker";
import {Time} from "animation-utilities";
import { IDLabels, SensoryType } from "./DataTypes";
import {SensoryRecord, SensoryHandler} from "./SensoryRecord";
import {SimpleIDTracker} from "./SimpleIDTracker";
import {AnybodyTracker} from "./AnybodyTracker";
import JiboLog = require('jibo-log');
import {SpeakerId, SpeakerIdRecord, Speaker, SID_Status, IndividualSpeaker} from 'jibo-common-types';
/**
 * @typedef jibo.lps.identity#LPSFaceIdentityEntry
 * @description
 * Data for LPS Face Entities
 * @prop {String} name Name of entity.
 * @prop {String} kind Kind of possible entity.
 * @prop {Number} confidence Confidence we have at this entry identification.
 * @internal
 */
interface LPSFaceIdentityEntry {
    name:string;
    kind:string;
    confidence:number;
}
/**
 * @typedef jibo.lps.identity#LPSWakeIdentityEntry
 * @description
 * ID of entities when called by LPS Wake up.
 * @prop {Array<string, number>} speakers Speakers that have been identitied in an array of `{speaker_id,score}`
 * @prop {string} status Status
 * @internal
 */
interface LPSWakeIdentityEntry {
    speakers:{speaker_id:string,score:number}[];
    status:string;
}
/**
 * @typedef jibo.lps.identity#StateChanges
 * @internal
 * @description State changes for a track. Maps from ID to direction of state and the reason. `[id:string]:{direction:boolean, reason:string}`
 */
export interface StateChanges {
    [id:string]:{direction:boolean, reason:string};
}
/**
 * @typedef jibo.lps.identity#TimeTracks
 * @description Timing information for Tracks.
 * @prop {Boolean} present `true` if the entity is currently present.
 * @prop {Time} lastSeen Last time the track was seen.
 * @prop {Time} lastHeard Last time the track was heard.
 * @internal
 */
type TimeTracks = {
    present: boolean,
    lastSeen: Time,
    lastHeard: Time
}

/**
 * @description
 * Manager wrapper for all sensory inputs.
 * @memberOf jibo.lps.identity
 * @class TrackerManager
 * @internal
 */
export default class TrackerManager implements SensoryHandler {

    private trackers:Map<string,Tracker>;
    private trackStates:Map<string, TimeTracks>;
    private listener:{(stateChanges:StateChanges): void};
    private log:JiboLog;

    constructor(listener:{(stateChanges:StateChanges): void}, log:JiboLog) {
        this.log = log;
        this.trackers = new Map<string, Tracker>();
        this.trackStates = new Map<string, TimeTracks>();
        this.trackers.set(IDLabels.ANYBODY, new AnybodyTracker());
        this.listener = listener;
    }

    /**
     * @description Add data to a sensory record
     * @param {jibo.lps.identity.SensoryRecord} sensoryRecord SensoryRecord to add to.
     * @method jibo.lps.identity.TrackerManager#addData
     */
    public addData(sensoryRecord:SensoryRecord) {

        let extracted = this.extractID(sensoryRecord);

        let primaryID:string = null;
        let idRecord:IDRecord = null;
        if(extracted!==null){
            primaryID = extracted[0];
            idRecord = extracted[1];
        }

        if(idRecord!==null && primaryID!==null){

            //let's make sure we have a tracker for the primary ID element:
            if(!this.trackers.has(primaryID)){
                //console.log("IDevents: Adding tracker "+primaryID+" for id seen by sensors");
                this.trackers.set(primaryID, this.createTrackerForID(primaryID));
            }
        }

        let iter = this.trackers.values(); //don't use for of for optimizer
        let nextVal:IteratorResult<Tracker>;
        while (!(nextVal = iter.next()).done) {
            let tracker = nextVal.value;
            tracker.handleRecord(sensoryRecord, idRecord);
        }
    }

    /**
     * @description set present person as ground truth
     * @param {Time} currentTime Time in which entity was seen.
     * @param {String} id ID of entity to set
     * @param {Boolean} isSpeaking Whether or not person is speaking
     * @method jibo.lps.identity.TrackerManager#setPresentPerson
     */
    public setPresentPerson(currentTime:Time, id:string, isSpeaking:boolean) {

        //let's make sure we have a tracker for the primary ID element:
        let tracker = this.trackers.get(id);
        if(tracker === undefined){
            //console.log("IDevents: Adding tracker "+id+" for top down assertion");
            tracker = this.createTrackerForID(id);
            this.trackers.set(id, tracker);
        }

        tracker.setIsPresent(currentTime, true, isSpeaking);
        this.trackers.get(IDLabels.ANYBODY).setIsPresent(currentTime, true, isSpeaking);

        this.update(currentTime);
    }

    /**
     * @description One update tick of Tracker.
     * @param {Time} currentTime Time at which update occurs
     * @method jibo.lps.identity.TrackerManager#update
     */
    public update(currentTime:Time) {
        //map from id to boolean; true meaning became active, false meaning became inactive
        let stateChanges:StateChanges = {};

        let iter = this.trackers.entries(); //don't use for of for optimizer
        let nextVal:IteratorResult<[string, Tracker]>;
        let finishedTrackers:string[] = null;

        while (!(nextVal = iter.next()).done) {
            let tracker = nextVal.value[1];
            let id = nextVal.value[0];

            let trackState = this.trackStates.get(id);
            if (trackState === undefined) { //init if not present
                trackState = {
                    present: false,
                    lastSeen: null,
                    lastHeard: null
                };
                this.trackStates.set(id, trackState);
            }

            tracker.update(currentTime);
            let present = tracker.getIsPresent();

            if(trackState.present!==present) {
                trackState.present = present;
                stateChanges[id]={direction:present, reason:tracker.getPresenceReason()};
            }
            if (present) {
                trackState.lastSeen = currentTime;
                trackState.lastHeard = tracker.lastSpokeTime;
            }

            let shouldDelete = tracker.getShouldDelete();
            //we'll remove trackers later to avoid potential issues modifying map while iterator is live
            if (shouldDelete) {
                if (finishedTrackers === null) {
                    finishedTrackers = [];
                }
                finishedTrackers.push(id);
            }
        }

        if (finishedTrackers !== null) {
            for (let i = 0; i < finishedTrackers.length; i++) {
                let finishedTrackerID = finishedTrackers[i];
                this.trackers.delete(finishedTrackerID);
                //console.log("IDEvents: Removing tracker " + finishedTrackerID);

                //make sure we mark the entry as no longer present, in case the tracker hasn't
                let trackState = this.trackStates.get(finishedTrackerID);
                if (trackState !== undefined && trackState.present === true) {
                    trackState.present = false;
                    //mark this as a state change
                    if(stateChanges[finishedTrackerID] && stateChanges[finishedTrackerID].direction === true){
                        //if this frame we were about to indicate "became active", instead indicate nothing
                        delete stateChanges[finishedTrackerID];
                    }else {
                        //otherwise, mark it as becoming inactive
                        stateChanges[finishedTrackerID] = {direction:false, reason:null};
                    }
                }
            }
        }

        this.processChanges(stateChanges);
    }

    /**
     * @description get the current state of the Tracks
     * @returns {Map} Map of track IDs to states.
     * @method jibo.lps.identity.TrackerManager#getState
     */
    public getState():Map<string, {present:boolean, lastSeen:any, lastHeard:any}>{
        return this.trackStates;
    }


    /**
     * @description process all changes from an update tick
     * @param {StateChanges} All the changes to process.
     * @method jibo.lps.identity.TrackerManager#processChanges
     * @private
     */
    private processChanges(stateChanges:StateChanges){
        if(this.listener!==null && stateChanges!==null) {
            this.listener(stateChanges);
        }
    }

    /**
     * @description create a simple id tracker for given ID.
     * @param {String} id to create tracker for
     * @returns {Tracker} Tracker for the Id.
     * @method jibo.lps.identity.TrackerManager#createTrackerForID
     * @private
     */
    private createTrackerForID(id:string):Tracker{
        return new SimpleIDTracker(id, this.log);
    }

    // this might just all be different
    // because now Todd has identity summary
    // also Todd might be doing his own thresholding?
    /**
     * @description extract ID for a record.
     * @param {SensoryRecord} record to extract ID for.
     * @returns {Array<string, IDRecord>} Id string and record for sensory record.
     * @method jibo.lps.identity.TrackerManager#extractID
     * @private
     */
    private extractID(sensoryRecord:SensoryRecord):[string,IDRecord] {//TODO: grab types from DataTypes
        if (sensoryRecord.type === SensoryType.AUDIO_LOCALIZATION) {
            return null;
        } else if (sensoryRecord.type === SensoryType.MOTION) {
            return null;
        } else if (sensoryRecord.type === SensoryType.FACE) {
            let identity = <LPSFaceIdentityEntry[]>sensoryRecord.raw.identity;

            if (identity !== null && identity !== undefined && identity.length > 0) {
                let idRecord = new IDRecord();
                for (let i = 0; i < identity.length; i++) {
                    idRecord[identity[i].name] = identity[i].confidence;
                }
                let primaryID = identity[0].name;
                //console.log("IDEvents: Saw ID from face:" + identity[0].name+", "+identity[0].confidence);
                //this.log.info("IDEvents: Saw ID from face:" + identity[0].name+", "+identity[0].confidence);
                return [primaryID, idRecord];
            }
            // dont' have to do the wake word stuff anymore?
        } else if (sensoryRecord.type === SensoryType.WAKE) {
            let speakerId = <any>sensoryRecord.raw;
            if (speakerId !== null && speakerId !== undefined) {
                if(speakerId.status === SID_Status.NOT_USED){
                    return null;
                    //this is either the first part (non-id'd) of a HJ, or an id with no info
                    // (no one enrolled on bot, or we're in simulator with "no id" selected)
                    //these known cases would also return null because of the zero-length speakers list check,
                    // but this way we won't consider it a format error
                }
                // SpeakerId and SpeakerIdRecord to comply with >=3.0.0 and <3.0.0
                let speakers = (speakerId as SpeakerIdRecord).speaker_id || (speakerId as SpeakerId).speakers;
                if (speakers !== null && speakers !== undefined && speakers.length > 0) {
                    let idRecord = new IDRecord();
                    let confidence = 1;
                    // Again, account for two different data streams.
                    let accepted = (speakerId.status === SID_Status.ACCEPTED) || ((speakers[0] as IndividualSpeaker).SID_Status === SID_Status.ACCEPTED);
                    //there is meant to be exactly 1
                    if(speakers.length!==1) {
                        this.log.warn("IDEvents expected exactly 1 speakers, got:"+JSON.stringify(sensoryRecord.raw));
                    }
                    let primaryID = null;
                    if(accepted) {
                        // Individual speaker -- >=3.0.0
                        if((speakers[0] as IndividualSpeaker).ID) {
                            idRecord[(speakers[0] as IndividualSpeaker).ID] = confidence;
                            primaryID = (speakers[0] as IndividualSpeaker).ID;
                        }
                        // old speaker -- <3.0.0
                        else if((speakers[0] as Speaker).speaker_id) {
                            idRecord[(speakers[0] as Speaker).speaker_id] = confidence;
                            primaryID = (speakers[0] as Speaker).speaker_id;
                        }
                    }
                    else {
                        idRecord[IDLabels.NOT_ENROLLED] = confidence;
                        primaryID = IDLabels.NOT_ENROLLED;
                    }
                    //console.log("IDEvents: Saw ID from wake:" + speakers[0].speaker_id+", accepted="+accepted);
                    this.log.info("IDEvents: Saw ID from wake:" + primaryID+", ACCEPTED="+accepted);
                    return [primaryID, idRecord];
                }
                else {
                    this.log.warn("IDEvents: Got wake speakerID with no speakers!!:"+JSON.stringify(sensoryRecord.raw));
                }
            }
            else {
                this.log.warn("IDEvents: Got wake with no speakerID!!:"+JSON.stringify(sensoryRecord.raw));
            }
        }
        return null;
    }

}
