import {SimpleTracker} from "./SimpleTracker";
import {IDLabels, SensoryType} from "./DataTypes";

/**
 * @class AnybodyTracker
 * @description Tracks any type of entity.
 * @memberOf jibo.lps.identity
 * @internal
 */
export class AnybodyTracker extends SimpleTracker
{
    constructor()
    {
        super(IDLabels.ANYBODY);

        this.hardTimeoutsFast[SensoryType.FACE] = 20;
        this.hardTimeoutsFast[SensoryType.WAKE] = 90;
        this.hardTimeoutsFast[SensoryType.GROUND_TRUTH] = 90;

        this.hardTimeoutsSlow[SensoryType.FACE] = 60;
        this.hardTimeoutsSlow[SensoryType.WAKE] = 300;
        this.hardTimeoutsSlow[SensoryType.GROUND_TRUTH] = 300;

        // Trust Todd's stuff, take soft timeouts away.
        this.softTimeouts[SensoryType.AUDIO_LOCALIZATION] = 5;
        this.softTimeouts[SensoryType.MOTION] = 8;

        this.deleteTimeout = Number.MAX_VALUE;
    }
}
