import Component from '../../Component';
import ActionData from '../../actions/ActionData';
import View from '../../views/View';
import TouchManager from '../../TouchManager';

/**
 * Manages touch/gesture interactions for GUI components.
 * @class TouchInteractive
 * @memberof jibo.face
 * @internal
 */
class TouchInteractive {

    /**
     * Whether interacivity is active or not.
     * @name jibo.face.TouchInteractive.isActive
     * @type {Boolean}
     */
    public isActive:boolean = false;

    /**
     * Object of array of actions, with gesture type as key.
     * @name jibo.face.TouchInteractive._gestureActions
     * @type {Object.<string, jibo.face.ActionData>}
     * @private
     */
    private _gestureActions:{} = null;

    /**
     * Owning Component.
     * @name jibo.face.TouchInteractive._component
     * @type {Boolean}
     * @private
     */
    private _component:Component = null;

    ///////////////////////////// CONSTRUCTION /////////////////////////////

    constructor(component:Component) {
        this._component = component;
        this._gestureActions = {};
    }

    /**
     * Destroy
     * @method jibo.face.TouchInteractive#destroy
     */
    public destroy():void {
        if(this._component){
            this._component = null;
        }
        this._gestureActions = null;
    }

    ////////////////////////////// ACTIONS //////////////////////////////


    /**
     * Add a {@link jibo.face.ActionData}. All actions with  will be triggered on triggerActions.
     * Generally these actions are triggered on a screen press (if a screen press is set up).
     * @method jibo.face.TouchInteractive#addAction
     * @param {jibo.face.ActionData} actionData - The action to be triggered on tap.
     * @param {boolean} [clearPrevious = false] Flag to determine if we should clear out the existing actions.
     * @param {boolean} [toFront = false] If `true` adds action to front of actions list, causing it to be called first when actions are triggered.
     * @param {String} [gesture = 'tap'] Gesture actions are related to.
     * @returns {jibo.face.ActionData} The ActionData added.
     */
    public addAction(actionData:ActionData, clearPrevious:boolean = false, toFront:boolean = false, gesture:string = TouchManager.PAN):ActionData {
        if (!this._gestureActions[gesture]) {
            this._gestureActions[gesture] = [];
        } else if (clearPrevious) {
            this._gestureActions[gesture].length = 0;
        }

        // if action is added to front or back of list
        if (toFront) {
            this._gestureActions[gesture].unshift(actionData);
        }
        else {
            this._gestureActions[gesture].push(actionData);
        }

        // add gesture (if it's not already there)
        TouchManager.instance.addGesture(gesture);

        return actionData;
    }

    /**
     * Returns `true` if there are actions associated with given gesture type.
     * @method jibo.face.TouchInteractive#hasActions
     * @param {string} [gesture = 'tap'] Gesture actions are related to.
     * @returns {boolean} `true` if there are actions associated with given gesture type.
     */
    public hasActions(gesture:string = TouchManager.TAP):boolean {
        return (this._gestureActions[gesture] && this._gestureActions[gesture].length > 0);
    }

    /**
     * Get actions associated with given gesture type.
     * @method jibo.face.TouchInteractive#getActions
     * @param {string} [gesture = 'tap'] Gesture actions are related to.
     * @return {jibo.face.ActionData[]} Actions associated with the given gesture type.
     */
    public getActions(gesture:string = TouchManager.TAP):ActionData[] {
        return this._gestureActions[gesture];
    }

    /**
     * Clear all actions associated with given gesture type.
     * @method jibo.face.TouchInteractive#clearActions
     * @param {string} [gesture = 'tap'] Gesture actions are related to.
     */
    public clearActions(gesture:string = TouchManager.TAP):void {
        delete this._gestureActions[gesture];
    }

    /**
     * Trigger actions associated with given gesture type.
     * Calls Component or the Component parent's actionHandler for each action.
     * @method jibo.face.TouchInteractive#triggerActions
     * @param {string} [gesture = 'tap'] Gesture actions are related to.
     */
    public triggerActions(gesture:string = TouchManager.TAP):void {
        if (this._gestureActions[gesture]) {
            if (this._component.parentGroup) {
                const actions:ActionData[] = this._gestureActions[gesture];
                for (let i:number = 0; i < actions.length; i++) {
                    this._component.parentGroup.actionHandler(actions[i], this._component);
                }
            }
            else if (this._component instanceof View) {
                const actions:ActionData[] = this._gestureActions[gesture];
                for (let i:number = 0; i < actions.length; i++) {
                    (<View>this._component).actionHandler(actions[i], this._component);
                }
            }
        }
    }
}

export default TouchInteractive;
