import IdentityInterface from "./IdentityServiceInterface";
import { IdentityEvents } from './IDEvents';
import { Person, IDLabels } from "./DataTypes";
import TrackerManager from "./TrackerManager";
import EventConverter from "./EventConverter";
import {Time, Clock} from "animation-utilities";
import {DataConverter} from "./DataConverter";
import JiboLog = require("jibo-log");
import GLService from "../gl/GLService";
import Runtime from "../../Runtime";
import LPSService from "../LPSService";


// https://confluence.jibo.com/display/ENG/LPS+Service
// THIS IS IMPORTANT.

/**
 * @description
 * Identity Module.
 * Get identity information from Jibo's LPS. including
 * present persons, present speaker, person location, as well as
 * detailed information about speaker and face ID.
 *
 * ```
 * var jibo = require("jibo");
 * jibo.lps.identity.getPresentPersons();
 * ```
 * @namespace jibo.lps.identity
 */
class Identity implements IdentityInterface {
    public events:IdentityEvents = new IdentityEvents();

    /**
     * @type {DataConverter}
     */
    private dataConverter:DataConverter;

    /**
     * @type {EventConverter}
     */
    private eventConverter:EventConverter;

    /**
     * @type {TrackerManager}
     */
    private trackerManager:TrackerManager;

    /**
     * Keep interval handler for unregistering when dispose is called
     */
    private intervalHandle:any = null;

    /**
     * Keep wake handler for unregistering when dispose is called
     */
    private wakeHandlerFunction:any = null;
    /**
     * Keep speaker ID handler for unregistering when dispose is called
     */
    private speakerIDHandlerFunction:any = null;

    private awaitingSpeakerID:boolean = false;
    private gotSpeakerID:boolean = false;
    /**
     * @type {Time}
     */
    private lastHJTime:any = null;
    private speakerIDTimeout:number = 3;

    private idResolutionListeners:Function[] = [];

    /**
     * Use this log for output
     */
    private log:JiboLog;
    /**
     * Use this log for output
     */
    private lps:LPSService;
    /**
     * Use this log for output
     */
    // private gl:GLService;

    /**
     * @param {JiboLog} log
     * @constructor
     */
    constructor(lps:LPSService, log = null){
        if(log === null){
            log = new JiboLog("jibo-id-events");
        }
        this.log = log;
        this.eventConverter = new EventConverter(this.events, log);
        this.trackerManager = new TrackerManager(this.eventConverter.processChanges.bind(this.eventConverter), log);
        //let attentionManagerReceiveWakeWord = {notifyWakeHappened:function(){;}}; //if we use the old version of DataConverter
        this.dataConverter = new DataConverter(this.trackerManager);
        this.lps = lps;
        // this.gl = Runtime.instance.gl;
        this.install();
    }

    /**
     * @description Returns true if one or more persons are present in the robot's environment.
     * @returns {boolean} `true` is someone is present.
     * @method jibo.lps.identity#isAnyonePresent
     */
    public isAnyonePresent(): boolean{
        let state = this.trackerManager.getState();
        let anyoneEntry = state.get(IDLabels.ANYBODY);
        if(anyoneEntry!==null && anyoneEntry!==undefined){
            return anyoneEntry.present;
        }else{
            return false;
        }
    }

    /**
     * @description Returns a list of persons who are present in the robot's environment.
     * Persons may be identified (known/in-loop) or unidentified.
     * @returns {Array<jibo.lps.identity#Person>} List of present persons.
     * @method jibo.lps.identity#getPresentPersons
     */
    public getPresentPersons(): Person[]{
        let state = this.trackerManager.getState();
        let persons:Person[] = [];

        let iter = state.entries(); //don't use for of for optimizer
        let nextVal:IteratorResult<[string, {present:boolean, lastSeen:any, lastHeard:any}]>;

        while (!(nextVal = iter.next()).done) {
            let id = nextVal.value[0];
            let state = nextVal.value[1];
            if(id !== IDLabels.ANYBODY && state.present){
                if( id === IDLabels.NOT_ENROLLED ) {
                    persons.push({id: null, type:IDLabels.NOT_ENROLLED}); //TODO: push type info deeper into rep.
                }else{
                    persons.push({id: id, type:IDLabels.IDENTIFIED}); //TODO: push type info deeper into rep.
                }
            }
        }
        return persons;
    }

    /**
     * @description Call this method to provide top-down ("ground truth") notification that a particular person is present
     * in the robot's environment.
     * @param {string} id - Unique ID of the person who is present.
     * @param {isSpeaking} [boolean] `true` if the person identified has recently spoken or said 'hey jibo'.
     * @method jibo.lps.identity#setPresentPerson
     */
    public setPresentPerson(id: string, isSpeaking:boolean = true):void {
        let time = Clock.currentTime();
        this.trackerManager.setPresentPerson(time, id, isSpeaking);
    }

    // Todd might have this in the new module?
    // speaking flag to ID summary?
    /**
     * @description Returns the most recent speaker out of the persons who are present in the robot's environment,
     * or null if no such person is present.
     * @returns {jibo.lps.identity#Person} Person who is speaking.
     * @method jibo.lps.identity#getActiveSpeaker
     */
    public getActiveSpeaker(): Person {
        let managerState = this.trackerManager.getState();
        let lastSpeaker:Person = null;
        let lastTime:Time;

        let iter = managerState.entries(); //don't use for of for optimizer
        let nextVal:IteratorResult<[string, {present:boolean, lastSeen:Time, lastHeard:Time}]>;

        while (!(nextVal = iter.next()).done) {
            let id = nextVal.value[0];
            let state = nextVal.value[1];
            //use the last heard person, only dealing with second accuracy for now - people
            //interrupting each other will be a nightmare anyway
            if(id !== IDLabels.ANYBODY && state.present && state.lastHeard && (!lastSpeaker || state.lastHeard.isGreater(lastTime))) {
                if(id === IDLabels.NOT_ENROLLED){
                    lastSpeaker = {id: null, type:IDLabels.NOT_ENROLLED}; //TODO: push type info deeper into rep
                }else{
                    lastSpeaker = {id: id, type:IDLabels.IDENTIFIED}; //TODO: push type info deeper into rep
                }
                lastTime = state.lastHeard;
            }
        }
        if(lastSpeaker === null && managerState.has(IDLabels.ANYBODY)
            && managerState.get(IDLabels.ANYBODY).present && managerState.get(IDLabels.ANYBODY).lastHeard){
            lastSpeaker = {id: null, type:IDLabels.ANYBODY};
        }
        return lastSpeaker;
    }

    /**
     * Call this method to be notified when any in-progress ID resolution completes.
     * For example, if we have heard "Hey Jibo" but are still waiting for speaker ID data, the provided callback
     * will be called as soon as the anticipated ID data has been received and incorporated.
     * The provided callback will be called immediately if no ID resolution is in-progress.
     * The callback will be called exactly once.
     * @method jibo.lps.identity#awaitResolution
     * @param {Function} cb - The callback to call upon ID resolution; called immediately if no resolution is in-progress.
     */
    public awaitResolution(cb: Function){
        if(this.awaitingSpeakerID){
            this.idResolutionListeners.push(cb);
        }else{
            cb();
        }
    }

    /**
     * Call to stop using and release this instance.
     * De-register listeners that this class has installed, stop internal event loop.
     * @method jibo.lps.identity#dispose
     */
    public dispose(){
        if(this.intervalHandle!==null){
            clearInterval(this.intervalHandle);
            this.intervalHandle = null;
        }
        if(this.wakeHandlerFunction!==null){
            Runtime.instance.gl.events.hjHeard.removeListener(this.wakeHandlerFunction);
            this.wakeHandlerFunction = null;
        }
        if(this.speakerIDHandlerFunction!==null){
            Runtime.instance.gl.events.speakerId.removeListener(this.speakerIDHandlerFunction);
            this.speakerIDHandlerFunction = null;
        }
    }

    private install(){

        if(this.intervalHandle !== null || this.wakeHandlerFunction !== null){
            throw new Error("IDEvents being installed, but it is already installed!");
        }

        this.intervalHandle = setInterval(() => {
            if(this.lps) {
                this.dataConverter.acceptAudioLocalization(this.lps.audioData);
                this.dataConverter.acceptVision(this.lps.motionData);
            }
            this.update();
        }, 33);

        //TODO: get non HJ speech as well!
        // probably don't need to do all this GL gobbldeegook
        if(Runtime.instance.gl===null || Runtime.instance.gl===undefined) {
            this.log.error('IDEvents initted without glService.  GLService='+GLService);
        }else{
            this.wakeHandlerFunction = (data) => {
                this.dataConverter.acceptWakeWord(data.speakerId);
                this.awaitingSpeakerID = true;
                this.lastHJTime = Clock.currentTime();
            };
            Runtime.instance.gl.events.hjHeard.on(this.wakeHandlerFunction);

            if(Runtime.instance.gl.events.speakerId){
                this.speakerIDHandlerFunction = (data) => {
                    this.dataConverter.acceptWakeWord(data);
                    if(this.awaitingSpeakerID){
                        this.gotSpeakerID = true;
                    }
                };
                Runtime.instance.gl.events.speakerId.on(this.speakerIDHandlerFunction);
            }
        }
    }

    // TODO ask M&J about this
    private update(){
        let time = Clock.currentTime();
        this.trackerManager.update(time);

        if(this.awaitingSpeakerID){
            if(this.gotSpeakerID || time.subtract(this.lastHJTime) > this.speakerIDTimeout){
                this.awaitingSpeakerID = false;
                this.gotSpeakerID = false;

                // notify listeners
                while(this.idResolutionListeners.length > 0){
                    let cb = this.idResolutionListeners.shift();
                    cb();
                }
            }
        }
    }

}

export default Identity;
