import { Event as TypedEvent, EventContainer, EmitterMode } from 'jibo-typed-events';
import { ListenResults } from 'jibo-common-types';

/**
 * @class GlobalEvents
 * @description Typed global events for gl module (`jibo.gl.global`).
 * Only emits event to LAST subscriber.
 * Also emits when a subscriber is added to a particular event AND
 * when all subscribers have been removed from particular event (no handlers
 * are registered for that event).
 * ```
 * function handler = (data) => {
 *    // data is of type asrResult
 *    // the ASR service has finished listening a cloud result
 *    // and all subscribed listeners will be removed
 * }
 * jibo.gl.global.help.on(handler);
 * // When finished with event listening
 * jibo.gl.global.help.removeLastListener();
 * // or
 * jibo.gl.global.help.removeListener(handler);
 * ```
 * @memberof jibo.gl
 */
export class GlobalEvents extends EventContainer {
    public stop: GlobalEvent<ListenResults>;
    public help: GlobalEvent<ListenResults>;
    public sleep: GlobalEvent<ListenResults>;
    public pause: GlobalEvent<ListenResults>;
    public volume: GlobalEvent<ListenResults>;
    public whatCanIDo: GlobalEvent<ListenResults>;

    constructor() {
        super();
        /**
         * Global stop command received
         * @name jibo.gl.GlobalEvents#stop
         * @type {GlobalEvent}
         */
        this.stop = new GlobalEvent<ListenResults>('Received global stop command');
        this.stop.setMode(EmitterMode.LAST_HANDLER);
        /**
         * Received global help command
         * @name jibo.gl.GlobalEvents#help
         * @type {GlobalEvent}
         */
        this.help = new GlobalEvent<ListenResults>('Received global help command');
        this.help.setMode(EmitterMode.LAST_HANDLER);
        /**
         * Received global sleep command
         * @name jibo.gl.GlobalEvents#sleep
         * @type {GlobalEvent}
         */
        this.sleep = new GlobalEvent<ListenResults>('Received global sleep command');
        this.sleep.setMode(EmitterMode.LAST_HANDLER);
        /**
         * Received global pause command
         * @name jibo.gl.GlobalEvents#pause
         * @type {GlobalEvent}
         */
        this.pause = new GlobalEvent<ListenResults>('Received global pause command');
        this.pause.setMode(EmitterMode.LAST_HANDLER);
        /**
         * Received global volume command
         * @name jibo.gl.GlobalEvents#volume
         * @type {GlobalEvent}
         */
        this.volume = new GlobalEvent<ListenResults>('Received global volume command');
        this.volume.setMode(EmitterMode.LAST_HANDLER);
        /**
         * Received global whatCanIDo
         * @name jibo.gl.GlobalEvents#whatCanIDo
         * @type {GlobalEvent}
         */
        this.whatCanIDo = new GlobalEvent<ListenResults>('Received global whatCanIDo command');
        this.whatCanIDo.setMode(EmitterMode.LAST_HANDLER);
    }
}

/**
 * @description Interface for an event handler function
 * @typedef Handler
 * @name jibo.gl.GlobalEvent~Handler
 */
export interface Handler <Type> {
    (data?: Type): void;
}

/**
 * @class GlobalEvent
 * @description Typed global event for gl module (`jibo.gl.global`).
 * In addition to subscribing to events, allows a special meta-subscribe
 * event which fires whenever a listener is added and when the last listener
 * is removed.
 * ```
 * function handler = (data) => {
 *    // data is of type asrResult
 *    // the ASR service has finished listening a cloud result
 *    // and all subscribed listeners will be removed
 * }
 * jibo.gl.global.help.on(handler);
 * // When finished with event listening
 * jibo.gl.global.help.removeLastListener();
 * // or
 * jibo.gl.global.help.removeListener(handler);
 * ```
 * @memberof jibo.gl
 */
export class GlobalEvent <Type> extends TypedEvent <Type> {
    private _subscriberOff: Handler<Type>[] = [];
    private _subscriberOn: Handler<Type>[] = [];

    constructor(name:string) {
        super(name);
    }

    checkLastListener() {
        if(this.listenerCount() === 0) {
            this.emitNoListeners();
        }
    }

    /**
     * Subscribes a handler for once no other listeners are subscribed.
     * @method jibo.gl.GlobalEvent#onNoListeners
     * @return {GlobalEvent} this
     */
    onNoListeners(handler: Handler<Type>) {
        this._subscriberOff.push(handler);
        return this;
    }

    /**
     * Emit that we have no subscribed listeners to all handlers.
     * @method jibo.gl.GlobalEvent#emitNoListeners
     */
    emitNoListeners() {
        // We start by creating a copy of handlers
        // this is required to make sure that no handler modifies the
        // underlying collection which could result in one or more
        // handlers not being called
        let copy = this._subscriberOff.slice();
        for (let i = 0; i < copy.length; i++ ) {
            let handler: any = copy[i] as any;
            handler();
        }
    }

    /**
     * Subscribes a handler for every time another listener subscribes.
     * @method jibo.gl.GlobalEvent#onAddedListener
     * @return {GlobalEvent} this
     */
    onAddedListener(handler: Handler<Type>) {
        this._subscriberOn.push(handler);
        return this;
    }

    /**
     * Emit that we added a subscriber to the typed event.
     * @method jibo.gl.GlobalEvent#emitAddListener
     */
    emitAddListener() {
        // We start by creating a copy of handlers
        // this is required to make sure that no handler modifies the
        // underlying collection which could result in one or more
        // handlers not being called
        let copy = this._subscriberOn.slice();
        for (let i = 0; i < copy.length; i++ ) {
            let handler: any = copy[i] as any;
            handler();
        }
    }

    /**
     * Subscribes a handler function to this event (same as `addListener`)
     * @method jibo.gl.GlobalEvent#on
     * @return {GlobalEvent} this
     */
    on(handler: Handler<Type>) {
        this.emitAddListener();
        return super.on(handler);
    }

    /**
     * Subscribes a handler function to only the next event
     * @method jibo.gl.GlobalEvent#once
     * @return {GlobalEvent} this
     */
    once(handler: Handler<Type>) {
        this.emitAddListener();
        return super.once(handler);
    }

    /**
     * Subscribes a handler function to this event (same as `on`)
     * @method jibo.gl.GlobalEvent#addListener
     * @return {GlobalEvent} this
     */
    addListener(handler: Handler<Type>) {
        this.emitAddListener();
        return super.addListener(handler);
    }

    /**
     * Unsubscribes a handler function from this event
     * @method jibo.gl.GlobalEvent#removeListener
     * @param {jibo.gl.GlobalEvent~Handler} handler Handler to unsubscribe.
     * @return {GlobalEvent} this
     */
    removeListener(handler: Handler<Type>) {
        const result = super.removeListener(handler);
        this.checkLastListener();
        return result;
    }

    /**
     * Unsubscribes all handler functions from this event
     * @method jibo.gl.GlobalEvent#removeAllListeners
     * @return {GlobalEvent} this
     */
    removeAllListeners() {
        this.emitNoListeners();
        return super.removeAllListeners();
    }

    /**
     * Unsubscribes oldest added subscriber
     * @method jibo.gl.GlobalEvent#removeFirstListener
     * @return {GlobalEvent} this
     */
    removeFirstListener() {
        const result = super.removeFirstListener();
        this.checkLastListener();
        return result;
    }

    /**
     * Unsubscribes most recently added subscriber
     * @method jibo.gl.GlobalEvent#removeLastListener
     * @return {GlobalEvent} this
     */
    removeLastListener() {
        const result = super.removeLastListener();
        this.checkLastListener();
        return result;
    }
}
