import {SensoryRecord, SensoryHandler} from "./SensoryRecord";
import {SensoryType} from "./DataTypes";
import {Clock, Time as TimeType} from "animation-utilities";

let AnimationUtilities = require("animation-utilities");
let THREE = AnimationUtilities.THREE;
let Time = AnimationUtilities.Time;

/**
 * @description
 * Convert data from various raw forms into standardized SensoryRecords, add them to the sensory store.
 * @class DataConverter
 * @memberOf jibo.lps.identity
 * @internal
 */
export class DataConverter{

    /** @type {SensoryHandler} */
    private _sensoryHandler:SensoryHandler;
    /** @type {Time} */
    private _lastVisionTimestamp:TimeType = null;

    /**
     * @param {SensoryHandler} sensoryHandler
     * @constructor
     */
    constructor(sensoryHandler:SensoryHandler){
        this._sensoryHandler = sensoryHandler;
    }

    /**
     * @method jibo.lps.identity.DataConverter#acceptAudioLocalization
     * @description convert audio localization data to our format
     * @param {any} data from LPS Service
     */
    acceptAudioLocalization(data:any){
        for(let aei = 0; aei < data.entities.length; aei++){
            let sr = new SensoryRecord(
                SensoryType.AUDIO_LOCALIZATION,
                new THREE.Vector3(data.entities[aei].position.x, data.entities[aei].position.y, data.entities[aei].position.z),
                data.entities[aei],
                Clock.currentTime(),
                new Time(data.entities[aei].ts[0], data.entities[aei].ts[1]),
                data.entities[aei].id,
                data.entities[aei].confidence
            );
            this._sensoryHandler.addData(sr);
        }
    }

    /**
     * @method jibo.lps.identity.DataConverter#acceptVision
     * @description convert visual data data to our format
     * @param {any} data from LPS Service
     */
    acceptVision(data:any){
        let dataTimestamp = new Time(data.ts[0], data.ts[1]);
        if(this._lastVisionTimestamp === null || !this._lastVisionTimestamp.equals(dataTimestamp)){
            this._lastVisionTimestamp = dataTimestamp;
            let entities = data.entities;
            for(let vei = 0; vei < entities.length; vei++){
                let sensoryType = SensoryType.FACE;
                if(entities[vei].description === "motion"){
                    sensoryType = SensoryType.MOTION;
                }
                let sr = new SensoryRecord(
                    sensoryType,
                    new THREE.Vector3(entities[vei].position.x, entities[vei].position.y, entities[vei].position.z),
                    entities[vei],
                    Clock.currentTime(),
                    dataTimestamp,
                    entities[vei].id,
                    entities[vei].confidence
                );
                this._sensoryHandler.addData(sr);
            }
        }
    }

    /**
     * @method jibo.lps.identity.DataConverter#acceptWakeWord
     * @description convert wake data to our format
     * @param {any} data from LPS Service
     */
    acceptWakeWord(data:any){
        //console.log("Hey Jibo!!");
        //console.log("wake:"+JSON.stringify(data, null, "\t"));
        let sr = new SensoryRecord(
            SensoryType.WAKE,
            null,
            data,
            Clock.currentTime(),
            null,
            null,
            null
        );
        this._sensoryHandler.addData(sr);
    }

}
