import {Tracker, IDRecord} from "./Tracker";
import {SensoryType} from "./DataTypes";
import {SensoryRecord} from "./SensoryRecord";
import {Time} from "animation-utilities";

export type CustomIDSelector = (idRecord:IDRecord, threshold:number) => string;

/**
 * @description
 * A simple tracker for a single entity with abstract ID
 * @memberOf jibo.lps.identity
 * @class SimpleTracker
 * @internal
 */
export abstract class SimpleTracker implements Tracker
{
    protected id:string;

    protected isPresent:boolean = false;
    protected presenceReason:string = null;

    /**
     * @type {Time}
     */
    protected currentTime:Time = null;

    /**
     * @type {Object.<string, Time>}
     */
    protected hardEvidenceTimes:{[sensoryType:string]:Time} = {};
    /**
     * @type {Object.<string, Time>}
     */
    protected softEvidenceTimes:{[sensoryType:string]:Time} = {};

    /**
     * @type {Object.<string, number>}
     */
    protected hardTimeoutsFast:{[sensoryType:string]:number} = {};
    /**
     * @type {Object.<string, number>}
     */
    protected hardTimeoutsSlow:{[sensoryType:string]:number} = {};
    /**
     * @type {Object.<string, number>}
     */
    protected softTimeouts:{[sensoryType:string]:number} = {};

    /**
     * @type {Object.<string, CustomIDSelector>}
     */
    protected customWinnerSelectors:Object = {};

    /**
     * @type {Time}
     */
    protected lastActiveTime:Time = null;
    protected deleteTimeout:number = 120;

    /**
     * @type {Object.<string, number>}
     */
    protected hardThresholds:{[sensoryType:string]:number} = {};

    protected audioConfidenceThreshold:number = 0.5;

    /**
     * When the last time this person spoke was - this allows us to use 'the last person to speak'
     * as the person currently speaking to Jibo.
     * @type {Time}
     * @member jibo.lps.identity.SimpleTracker#lastSpokeTime
     * @default null
     */
    public lastSpokeTime:Time = null;


    constructor(id:string)
    {
        this.id = id;
    }

    /**
     * @return {string}
     * @method jibo.lps.identity.SimpleTracker#getID
     */
    getID():string
    {
        return this.id;
    };

    /**
     * @method jibo.lps.identity.SimpleTracker#handleRecord
     * @param {jibo.lps.identity.SensoryRecord} sensoryRecord
     * @param {jibo.lps.identity.Tracker#IDRecord} idRecord
     */
    handleRecord(sensoryRecord:SensoryRecord, idRecord:IDRecord)
    {
        if (this.acceptRecord(sensoryRecord))
        {
            let type:string = sensoryRecord.type;
            let timestamp:Time = sensoryRecord.receivedAt;
            let evidenceUsed:boolean = false;

            if (this.hardTimeoutsFast.hasOwnProperty(type))
            {
                // potential hard evidence

                if (this.hardThresholds.hasOwnProperty(type))
                {
                    let winner:string;
                    let customSelector = this.customWinnerSelectors[type];
                    if(customSelector){
                        winner = customSelector(idRecord, this.hardThresholds[type]);
                    }else{
                        winner = this.getWinnerOverThreshold(idRecord, this.hardThresholds[type]);
                    }
                    if (winner === this.id)
                    {
                        // I'm the winner -> hard evidence
                        this.hardEvidenceTimes[type] = timestamp;
                        evidenceUsed = true;
                    }
                    else if (winner === null && this.softTimeouts.hasOwnProperty(type))
                    {
                        // no winner -> soft evidence
                        this.softEvidenceTimes[type] = timestamp;
                        evidenceUsed = true;
                    }
                    else
                    {
                        // someone else is the winner (or I don't care) -> no evidence
                    }
                }
                else
                {
                    // no threshold necessary -> hard evidence
                    this.hardEvidenceTimes[type] = timestamp;
                    evidenceUsed = true;
                }
            }
            else if (this.softTimeouts.hasOwnProperty(type))
            {
                // soft evidence
                this.softEvidenceTimes[type] = timestamp;
                evidenceUsed = true;
            }
            if (evidenceUsed &&
                (type === SensoryType.WAKE || type === SensoryType.GROUND_TRUTH)) {
                this.lastSpokeTime = timestamp;
            }
        }
    }

    /**
     * @method jibo.lps.identity.SimpleTracker#update
     * @param {jibo.visualize.Time} currentTime
     */
    update(currentTime:Time)
    {
        this.currentTime = currentTime;

        this.isPresent = false;
        this.presenceReason = null;

        let hardEvidence:string = this.getRecentEvidence(this.hardEvidenceTimes, this.hardTimeoutsFast, currentTime);
        if (hardEvidence !== null)
        {
            // recent hard evidence
            this.isPresent = true;
            this.presenceReason = hardEvidence;
        }
        else
        {
            hardEvidence = this.getRecentEvidence(this.hardEvidenceTimes, this.hardTimeoutsSlow, currentTime);
            if (hardEvidence !== null)
            {
                // semi-recent hard evidence

                let softEvidence:string = this.getRecentEvidence(this.softEvidenceTimes, this.softTimeouts, currentTime);
                if (softEvidence !== null)
                {
                    // semi-recent hard evidence + recent soft evidence
                    this.isPresent = true;
                    this.presenceReason = hardEvidence;
                }
            }
        }

        if (this.isPresent || this.lastActiveTime === null)
        {
            this.lastActiveTime = currentTime;
        }

        if (!this.isPresent)
        {
            // reset evidence
            this.hardEvidenceTimes = {};
            this.softEvidenceTimes = {};
            this.lastSpokeTime = null;
        }
    }

    /**
     * @method jibo.lps.identity.SimpleTracker#getIsPresent
     * @return {boolean}
     */
    getIsPresent():boolean
    {
        return this.isPresent;
    }

    /**
     * @param {Time} currentTime
     * @param {boolean} isPresent
     * @param {boolean} isSpeaking
     * @method jibo.lps.identity.SimpleTracker#setIsPresent
     */
    setIsPresent(currentTime:Time, isPresent:boolean, isSpeaking:boolean)
    {
        if (isPresent)
        {
            this.hardEvidenceTimes[SensoryType.GROUND_TRUTH] = currentTime;
            if (isSpeaking)
            {
                this.lastSpokeTime = currentTime;
            }
        }
        else
        {
            delete this.hardEvidenceTimes[SensoryType.GROUND_TRUTH];
        }
    }

    /**
     * @return {string} The type of sensory input that caused presence to activate
     * @method jibo.lps.identity.SimpleTracker#getPresenceReason
     */
    getPresenceReason():string
    {
        return this.presenceReason;
    }

    /**
     * @return {boolean}
     * @method jibo.lps.identity.SimpleTracker#getShouldDelete
     */
    getShouldDelete():boolean
    {
        return this.currentTime && this.lastActiveTime && this.currentTime.subtract(this.lastActiveTime) > this.deleteTimeout;
    }

    /**
     * @param {jibo.lps.identity.SensoryRecord} sensoryRecord
     * @method jibo.lps.identity.SimpleTracker#acceptRecord
     */
    protected acceptRecord(sensoryRecord:SensoryRecord):boolean
    {
        if (sensoryRecord.type === SensoryType.AUDIO_LOCALIZATION && sensoryRecord.confidence < this.audioConfidenceThreshold)
        {
            return false;
        }
        else
        {
            return true;
        }
    }

    /**
     * @param {jibo.lps.identity.Tracker#IDRecord} idRecord
     * @param {number} threshold
     * @method jibo.lps.identity.SimpleTracker#getWinnerOverThreshold
     * @return {string}
     */
    protected getWinnerOverThreshold(idRecord:IDRecord, threshold:number):string
    {
        if (idRecord !== null)
        {
            let ids = Object.keys(idRecord);
            let winner:string = null;
            let winningValue:number = threshold;

            for (let i=0; i<ids.length; i++)
            {
                if (idRecord[ids[i]] > winningValue)
                {
                    winner = ids[i];
                    winningValue = idRecord[ids[i]];
                }
            }

            return winner;
        }
        else
        {
            return null;
        }
    }

    /**
     * @param {Object.<string, Time>} evidence
     * @param {Object.<string, number>} timeouts
     * @param {Time} currentTime
     * @return {string} The sensory type of the recent evidence, if any
     * @method jibo.lps.identity.SimpleTracker#getRecentEvidence
     */
    protected getRecentEvidence(evidence:Object, timeouts:Object, currentTime:Time):string
    {
        let timeoutKeys = Object.keys(timeouts);
        for (let i=0; i<timeoutKeys.length; i++)
        {
            let evidenceTime = evidence[timeoutKeys[i]];
            if (evidenceTime && currentTime.subtract(evidenceTime) < timeouts[timeoutKeys[i]])
            {
                return timeoutKeys[i];
            }
        }

        // no recent evidence
        return null;
    }
}
