import {IDRecord} from "./Tracker";
import {SimpleTracker} from "./SimpleTracker";
import {SensoryType} from "./DataTypes";
import JiboLog = require('jibo-log');

/**
 * @description
 * A simple tracker for a single given entity ID
 * @memberOf jibo.lps.identity
 * @class SimpleIDTracker
 * @param id {String}
 * @param log {JiboLog}
 * @internal
 */
export class SimpleIDTracker extends SimpleTracker
{
    constructor(id:string, log:JiboLog = null)
    {
        super(id);

        this.hardTimeoutsFast[SensoryType.FACE] = 20;
        this.hardTimeoutsFast[SensoryType.WAKE] = 90;
        this.hardTimeoutsFast[SensoryType.GROUND_TRUTH] = 90;

        this.hardTimeoutsSlow[SensoryType.FACE] = 60;
        this.hardTimeoutsSlow[SensoryType.WAKE] = 300;
        this.hardTimeoutsSlow[SensoryType.GROUND_TRUTH] = 300;

        this.softTimeouts[SensoryType.FACE] = 8;
        this.softTimeouts[SensoryType.AUDIO_LOCALIZATION] = 5;
        this.softTimeouts[SensoryType.MOTION] = 8;

        this.hardThresholds[SensoryType.FACE] = 0.02;
        this.hardThresholds[SensoryType.WAKE] = 0.25;

        let minFaceRatio = 8;

        let lastPrintedC1:number = null;
        let lastPrintedC2:number = null;

        this.customWinnerSelectors[SensoryType.FACE] = function(idRecord:IDRecord, threshold:number){
            if (idRecord !== null){
                let ids = Object.keys(idRecord);
                if(ids.length < 2){
                    return null;
                    //can't have a ratio if there aren't 2...
                }
                let winner:string = null;
                let winningValue:number = 0;
                let runnerUp:number = 0;

                for (let i=0; i<ids.length; i++){
                    let value = idRecord[ids[i]];
                    if (value > winningValue){
                        runnerUp = winningValue;
                        winningValue = value;
                        winner = ids[i];
                    }else if(value > runnerUp){
                        runnerUp = value;
                    }
                }

                // new LPS has real confidence!
                 if(log!==null && (winningValue!==lastPrintedC1 || runnerUp!==lastPrintedC2)){
                     log.info("Considering Face: confidence="+winningValue+" runnerUp="+runnerUp+" ratio="+(winningValue / runnerUp)+
                     " ratioThreshold="+minFaceRatio+" magThreshold="+threshold+
                     " "+((winningValue > threshold && (winningValue / runnerUp) > minFaceRatio)?"ACCEPTED":"REJECTED"));
                     lastPrintedC1 = winningValue;
                     lastPrintedC2 = runnerUp;
                 }

                 if(winningValue > threshold && (winningValue / runnerUp) > minFaceRatio){
                    return winner;
                 }
                 else {
                    return null;
                 }
            }
            else {
                return null;
            }
        };

        this.deleteTimeout = 120;
    }
}
